package com.npcpermadeath;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class NpcPermadeathPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(NpcPermadeathPlugin.class);
		RuneLite.main(args);
	}
}

package com.npcpermadeath;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Map;
import org.junit.Test;

public class SpawnTotalsTest
{
	private static final int LUMBRIDGE = 12850;

	@Test
	public void countsPinsPerRegionAndNamesTheRegion()
	{
		String page = "{{Infobox Monster|name = Goblin}}\n"
			+ "==Locations==\n{{LocTableHead}}\n"
			+ "{{LocLine\n|name = Goblin\n|location = [[Lumbridge]]\n|levels = 2\n|members = n\n|mapID = 0\n|plane = 0\n"
			+ "|x:3245,y:3245|x:3250,y:3230|x:3100,y:3100\n|mtype = pin\n}}\n"
			+ "{{LocLine|name = Goblin|location = Between [[Lumbridge]] and [[Varrock|the city]]|mapID = 0|plane = 0|x:3259,y:3338|mtype = pin}}\n"
			+ "{{LocLine|name = Goblin|location = [[Goblin Cave]]|mapID = 2|x:3245,y:3245}}\n"
			+ "{{LocTableBottom}}";

		SpawnTotals.PageSpawns spawns = SpawnTotals.parse(page);

		assertEquals(Integer.valueOf(2), spawns.byRegion.get(LUMBRIDGE));
		assertEquals(Integer.valueOf(1), spawns.byRegion.get(((3100 >> 6) << 8) | (3100 >> 6)));
		assertEquals(Integer.valueOf(1), spawns.byRegion.get(((3259 >> 6) << 8) | (3338 >> 6)));
		assertEquals(3, spawns.byRegion.size());
		Map<Integer, String> labels = spawns.labels();
		assertEquals("Lumbridge", labels.get(LUMBRIDGE));
		assertEquals("Between Lumbridge and the city", labels.get(((3259 >> 6) << 8) | (3338 >> 6)));
	}

	@Test
	public void mostCommonLabelWinsARegion()
	{
		String page = "{{LocLine|location = [[Lumbridge]]|x:3245,y:3245|x:3246,y:3245}}"
			+ "{{LocLine|location = [[Lumbridge Castle]]|x:3220,y:3220}}";

		assertEquals("Lumbridge", SpawnTotals.parse(page).labels().get(LUMBRIDGE));
	}

	@Test
	public void pageWithoutLocationLinesYieldsNothing()
	{
		SpawnTotals.PageSpawns spawns = SpawnTotals.parse("{{Infobox Monster|name = Rat}} Some prose.");

		assertTrue(spawns.byRegion.isEmpty());
		assertTrue(spawns.labels().isEmpty());
		assertTrue(SpawnTotals.parse("").byRegion.isEmpty());
	}

	@Test
	public void unterminatedTemplateIsIgnored()
	{
		assertTrue(SpawnTotals.parse("{{LocLine|location = [[X]]|x:1,y:1").byRegion.isEmpty());
	}

	@Test
	public void placesSpanRegionsAndBorderKillsGoHome()
	{
		SpawnTotals totals = new SpawnTotals(null, null, null, null);
		String page = "{{LocLine|location = [[Lumbridge]]|x:3245,y:3245|x:3250,y:3230|x:3190,y:3280}}"
			+ "{{LocLine|location = [[Goblin Village]]|x:2957,y:3510}}";
		totals.put("Goblin", SpawnTotals.parse(page), 0);
		int west = ((3190 >> 6) << 8) | (3280 >> 6);

		assertEquals("Lumbridge", totals.label("Goblin", LUMBRIDGE));
		assertEquals("Lumbridge", totals.label("Goblin", west));
		// Pooled labels name a region for NPCs whose own page has none.
		assertEquals("Lumbridge", totals.label("Rat", LUMBRIDGE));
		assertNull(totals.label("Rat", 1));
	}

	@Test
	public void pipesInsideLinksDoNotSplitParameters()
	{
		assertEquals(java.util.Arrays.asList("a", "[[X|Y]] and {{T|u}}", "x:1,y:2"),
			SpawnTotals.splitParams("a|[[X|Y]] and {{T|u}}|x:1,y:2"));
	}

	@Test
	public void labelsAreCleanedOfMarkup()
	{
		assertEquals("Lumbridge Swamp", SpawnTotals.cleanLabel("[[Lumbridge Swamp]]"));
		assertEquals("the swamp", SpawnTotals.cleanLabel("[[Lumbridge Swamp|the swamp]]"));
		assertEquals("Varrock sewers", SpawnTotals.cleanLabel("'''Varrock''' sewers{{sic}} <!-- note -->"));
		assertNull(SpawnTotals.parse("{{LocLine|x:3245,y:3245}}").labels().get(LUMBRIDGE));
	}
}

package com.npcpermadeath;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.Point;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class LootWatcherTest
{
	private static final WorldPoint TILE = new WorldPoint(3245, 3245, 0);
	private static final WorldPoint OTHER_TILE = new WorldPoint(3246, 3245, 0);
	private static final Point SCENE = new Point(45, 45);

	private final LootWatcher loot = new LootWatcher();

	private static TileItem item(int id, int ownership)
	{
		return new FakeTileItem(id, ownership);
	}

	@Test
	public void myLootOnTheDeathTileIsRecognisedBeforeOrAfterTheDespawn()
	{
		loot.onItemSpawned(item(526, TileItem.OWNERSHIP_SELF), TILE, SCENE, 10);

		assertTrue(loot.sawLoot(TILE, 10));
		assertTrue(loot.sawMyLoot(TILE, 10));
		assertTrue(loot.sawMyLoot(TILE, 11));
		assertFalse(loot.sawMyLoot(TILE, 12));
		assertFalse(loot.sawMyLoot(OTHER_TILE, 10));
	}

	@Test
	public void someoneElsesLootIsLootButNotMine()
	{
		loot.onItemSpawned(item(526, TileItem.OWNERSHIP_OTHER), TILE, SCENE, 10);

		assertTrue(loot.sawLoot(TILE, 10));
		assertFalse(loot.sawMyLoot(TILE, 10));
	}

	@Test
	public void oldSpawnsAreForgotten()
	{
		loot.onItemSpawned(item(526, TileItem.OWNERSHIP_SELF), TILE, SCENE, 10);
		loot.tick(14);

		assertFalse(loot.sawLoot(TILE, 11));
	}

	@Test
	public void lootSpawnedAfterAHiddenDeathIsCursed()
	{
		TileItem bones = item(526, TileItem.OWNERSHIP_SELF);
		loot.armTile(TILE, 10);
		loot.onItemSpawned(bones, TILE, SCENE, 10);

		assertTrue(loot.isCursed(bones));
		assertTrue(loot.blocksMenu(526, 45, 45));
		assertFalse(loot.blocksMenu(526, 46, 45));
		assertFalse(loot.blocksMenu(527, 45, 45));
	}

	@Test
	public void lootSpawnedJustBeforeTheDespawnEventIsCursed()
	{
		TileItem bones = item(526, TileItem.OWNERSHIP_SELF);
		loot.onItemSpawned(bones, TILE, SCENE, 10);
		loot.armTile(TILE, 10);

		assertTrue(loot.isCursed(bones));
	}

	@Test
	public void unrelatedItemsOnTheTileStayUntouched()
	{
		TileItem old = item(526, TileItem.OWNERSHIP_NONE);
		loot.onItemSpawned(old, TILE, SCENE, 5);
		loot.tick(9);
		loot.armTile(TILE, 10);
		TileItem later = item(526, TileItem.OWNERSHIP_SELF);
		loot.onItemSpawned(later, TILE, SCENE, 13);

		assertFalse(loot.isCursed(old));
		assertFalse(loot.isCursed(later));
		assertEquals(0, loot.cursedCount());
	}

	@Test
	public void despawnedItemsAreForgotten()
	{
		TileItem bones = item(526, TileItem.OWNERSHIP_SELF);
		loot.armTile(TILE, 10);
		loot.onItemSpawned(bones, TILE, SCENE, 10);

		loot.onItemDespawned(bones);

		assertFalse(loot.isCursed(bones));
		assertFalse(loot.blocksMenu(526, 45, 45));
	}
}

package com.npcpermadeath;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.npcpermadeath.PermadeathTracker.SpawnOutcome;
import org.junit.Before;
import org.junit.Test;

public class PermadeathTrackerTest
{
	private static final int GOBLIN = 3029;
	private static final String NAME = "Goblin";
	private static final int LUMBRIDGE = 12850;
	private static final int WORLD = 301;
	private static final AreaKey AREA = new AreaKey(NAME, LUMBRIDGE);
	private static final long NOW = 1_700_000_000_000L;

	private final PermadeathTracker tracker = new PermadeathTracker();

	@Before
	public void setUp()
	{
		tracker.setCurrentWorld(WORLD);
	}

	private void kill(int index)
	{
		tracker.recordHit(index, 5, true);
		tracker.recordDeath(index, GOBLIN, NAME, LUMBRIDGE, 100);
		PermadeathTracker.PendingDeath death = tracker.takeDeath(index, GOBLIN);
		assertEquals(NAME, death.getName());
		assertEquals(AREA, tracker.countKill(index, GOBLIN, death.getName(), death.getRegion(), NOW));
	}

	@Test
	public void killIsMineOnlyWhenIDealtTheMostDamage()
	{
		assertFalse(tracker.isMyKill(7));

		tracker.recordHit(7, 3, true);
		tracker.recordHit(7, 2, false);
		assertTrue(tracker.isMyKill(7));

		tracker.recordHit(7, 4, false);
		assertFalse(tracker.isMyKill(7));
	}

	@Test
	public void tiedDamageGoesToWhoeverHitFirst()
	{
		tracker.recordHit(7, 4, true);
		tracker.recordHit(7, 4, false);
		assertTrue(tracker.isMyKill(7));

		tracker.recordHit(8, 4, false);
		tracker.recordHit(8, 4, true);
		assertFalse(tracker.isMyKill(8));
	}

	@Test
	public void zeroDamageFromMeIsNotAKill()
	{
		tracker.recordHit(7, 0, true);
		assertFalse(tracker.isMyKill(7));
	}

	@Test
	public void damageTallyResetsWhenTheKillIsCounted()
	{
		kill(7);

		assertFalse(tracker.isMyKill(7));
	}

	@Test
	public void killIsCountedAndTheNpcHiddenWhenItDespawns()
	{
		kill(7);

		assertEquals(1, tracker.kills(AREA));
		assertTrue(tracker.isHidden(7, GOBLIN));
		assertEquals(SpawnOutcome.EXACT, tracker.recordSpawn(7, GOBLIN, NAME, LUMBRIDGE, NOW));
		assertTrue(tracker.isDirty());
	}

	@Test
	public void deathWithoutDespawnCountsNothing()
	{
		tracker.recordDeath(7, GOBLIN, NAME, LUMBRIDGE, 100);

		assertTrue(tracker.isPending(7));
		assertEquals(0, tracker.kills(AREA));
		assertFalse(tracker.isHidden(7, GOBLIN));
	}

	@Test
	public void takeDeathOnlyMatchesTheDyingNpc()
	{
		tracker.recordDeath(7, GOBLIN, NAME, LUMBRIDGE, 100);

		assertNull(tracker.takeDeath(7, 9999));
		assertNull(tracker.takeDeath(8, GOBLIN));
		assertEquals(GOBLIN, tracker.takeDeath(7, GOBLIN).getNpcId());
		assertNull(tracker.takeDeath(7, GOBLIN));
	}

	@Test
	public void forgetDropsDamageAndPendingDeath()
	{
		tracker.recordHit(7, 9, true);
		tracker.recordDeath(7, GOBLIN, NAME, LUMBRIDGE, 100);

		tracker.forget(7);

		assertFalse(tracker.isMyKill(7));
		assertFalse(tracker.isPending(7));
	}

	@Test
	public void killingAnAlreadyHiddenNpcDoesNotDoubleCount()
	{
		kill(7);

		assertNull(tracker.countKill(7, GOBLIN, NAME, LUMBRIDGE, NOW + 1));
		assertEquals(1, tracker.kills(AREA));
	}

	@Test
	public void otherNpcsAreSubstitutedUpToTheKillCountOnAnotherWorld()
	{
		kill(7);
		kill(8);
		tracker.setCurrentWorld(WORLD + 1);

		assertEquals(SpawnOutcome.SUBSTITUTE, tracker.recordSpawn(50, GOBLIN, NAME, LUMBRIDGE, NOW));
		assertEquals(SpawnOutcome.SUBSTITUTE, tracker.recordSpawn(51, GOBLIN, NAME, LUMBRIDGE, NOW));
		assertEquals(SpawnOutcome.VISIBLE, tracker.recordSpawn(52, GOBLIN, NAME, LUMBRIDGE, NOW));
		assertTrue(tracker.isHidden(50, GOBLIN));
		assertFalse(tracker.isHidden(52, GOBLIN));
		assertEquals(2, tracker.hiddenHere(AREA));
	}

	@Test
	public void substitutesAreStickyWhenTheyComeBackIntoView()
	{
		kill(7);
		tracker.setCurrentWorld(WORLD + 1);
		tracker.recordSpawn(50, GOBLIN, NAME, LUMBRIDGE, NOW);

		assertEquals(SpawnOutcome.EXACT, tracker.recordSpawn(50, GOBLIN, NAME, LUMBRIDGE, NOW + 1));
		assertEquals(SpawnOutcome.VISIBLE, tracker.recordSpawn(51, GOBLIN, NAME, LUMBRIDGE, NOW + 1));
	}

	@Test
	public void exactKillsOnTheHomeWorldLeaveNoDeficit()
	{
		kill(7);

		assertEquals(SpawnOutcome.VISIBLE, tracker.recordSpawn(8, GOBLIN, NAME, LUMBRIDGE, NOW));
	}

	@Test
	public void killsInOneRegionDoNotHideNpcsInAnother()
	{
		kill(7);

		assertEquals(SpawnOutcome.VISIBLE, tracker.recordSpawn(8, GOBLIN, NAME, LUMBRIDGE + 1, NOW));
	}

	@Test
	public void killsOfOneTypeDoNotHideAnotherType()
	{
		kill(7);

		assertEquals(SpawnOutcome.VISIBLE, tracker.recordSpawn(8, 2, "Cow", LUMBRIDGE, NOW));
	}

	@Test
	public void renumberedIndexIsReleasedAndBackfilled()
	{
		kill(7);

		assertEquals(SpawnOutcome.VISIBLE, tracker.recordSpawn(7, 2, "Cow", LUMBRIDGE, NOW));
		assertFalse(tracker.isHidden(7, GOBLIN));
		assertEquals(0, tracker.hiddenHere(AREA));
		assertEquals(SpawnOutcome.SUBSTITUTE, tracker.recordSpawn(9, GOBLIN, NAME, LUMBRIDGE, NOW));
	}

	@Test
	public void staleRecordsArePrunedSoTheCountCanBeRefilled()
	{
		kill(7);

		tracker.prune(0, NOW + PermadeathTracker.RECORD_TTL_MS + 1);

		assertFalse(tracker.isHidden(7, GOBLIN));
		assertEquals(1, tracker.kills(AREA));
		assertEquals(SpawnOutcome.SUBSTITUTE, tracker.recordSpawn(9, GOBLIN, NAME, LUMBRIDGE, NOW));
	}

	@Test
	public void seeingARecordRefreshesIt()
	{
		kill(7);
		long later = NOW + PermadeathTracker.RECORD_TTL_MS - 1;
		tracker.recordSpawn(7, GOBLIN, NAME, LUMBRIDGE, later);

		tracker.prune(0, later + 10);

		assertTrue(tracker.isHidden(7, GOBLIN));
	}

	@Test
	public void stalePendingDeathsArePruned()
	{
		tracker.recordDeath(7, GOBLIN, NAME, LUMBRIDGE, 100);
		tracker.prune(100 + PermadeathTracker.PENDING_TTL_TICKS + 1, NOW);

		assertFalse(tracker.isPending(7));
		assertNull(tracker.takeDeath(7, GOBLIN));
	}

	@Test
	public void stateRoundTripsThroughSavedState()
	{
		kill(7);
		tracker.setCurrentWorld(WORLD + 1);
		tracker.recordSpawn(50, GOBLIN, NAME, LUMBRIDGE, NOW);
		PermadeathTracker.SavedState saved = tracker.toSaved();
		assertEquals(Integer.valueOf(1), saved.kills.get("12850/Goblin"));
		assertEquals(2, saved.hidden.size());

		PermadeathTracker fresh = new PermadeathTracker();
		fresh.setCurrentWorld(WORLD);
		fresh.load(saved);

		assertTrue(fresh.isHidden(7, GOBLIN));
		assertFalse(fresh.isHidden(50, GOBLIN));
		assertEquals(1, fresh.hiddenHere(AREA));
		fresh.setCurrentWorld(WORLD + 1);
		assertTrue(fresh.isHidden(50, GOBLIN));
		assertFalse(fresh.isDirty());
	}

	@Test
	public void loadSkipsMalformedEntries()
	{
		PermadeathTracker.SavedState saved = new PermadeathTracker.SavedState();
		saved.kills.put("garbage", 3);
		saved.kills.put("12850/Goblin", 0);
		saved.kills.put("12851/Cow", 2);
		saved.hidden.add(new PermadeathTracker.HiddenNpc(1, 2, WORLD, null, 12851, NOW));

		tracker.load(saved);

		assertEquals(2, tracker.totalKills());
		assertEquals(0, tracker.hiddenHere(new AreaKey("Cow", 12851)));
	}

	@Test
	public void releasingAHiddenNpcLeavesADeficitToBackfill()
	{
		kill(7);

		assertEquals(AREA, tracker.release(7));

		assertFalse(tracker.isHidden(7, GOBLIN));
		assertTrue(tracker.hasDeficit(AREA));
		assertEquals(1, tracker.kills(AREA));
		assertEquals(SpawnOutcome.SUBSTITUTE, tracker.recordSpawn(9, GOBLIN, NAME, LUMBRIDGE, NOW));
		assertFalse(tracker.hasDeficit(AREA));
		assertNull(tracker.release(7));
	}

	@Test
	public void rehomingMovesKillsAndHiddenRecordsToTheOtherChunk()
	{
		AreaKey border = new AreaKey(NAME, LUMBRIDGE + 1);
		tracker.countKill(7, GOBLIN, NAME, LUMBRIDGE + 1, NOW);
		tracker.countKill(8, GOBLIN, NAME, LUMBRIDGE, NOW);
		tracker.markSaved();

		tracker.rehome(border, LUMBRIDGE);

		assertEquals(0, tracker.kills(border));
		assertEquals(2, tracker.kills(AREA));
		assertEquals(2, tracker.hiddenHere(AREA));
		assertTrue(tracker.isHidden(7, GOBLIN));
		assertTrue(tracker.isDirty());
		assertEquals(SpawnOutcome.VISIBLE, tracker.recordSpawn(9, GOBLIN, NAME, LUMBRIDGE, NOW));
	}

	@Test
	public void movingSomeKillsTakesThatManyHiddenRecordsAlong()
	{
		kill(7);
		kill(8);
		kill(9);
		tracker.markSaved();
		AreaKey west = new AreaKey(NAME, LUMBRIDGE - 1);

		assertEquals(2, tracker.moveKills(AREA, LUMBRIDGE - 1, 2));

		assertEquals(1, tracker.kills(AREA));
		assertEquals(2, tracker.kills(west));
		assertEquals(1, tracker.hiddenHere(AREA));
		assertEquals(2, tracker.hiddenHere(west));
		assertTrue(tracker.isHidden(7, GOBLIN) && tracker.isHidden(8, GOBLIN) && tracker.isHidden(9, GOBLIN));
		assertTrue(tracker.isDirty());
		assertEquals(0, tracker.moveKills(AREA, LUMBRIDGE, 1));
		assertEquals(1, tracker.moveKills(AREA, LUMBRIDGE - 1, 5));
		assertEquals(0, tracker.kills(AREA));
	}

	@Test
	public void forgettingAnAreaBringsItsNpcsBackEverywhere()
	{
		kill(7);
		tracker.countKill(8, 2, "Cow", LUMBRIDGE, NOW);
		tracker.setCurrentWorld(WORLD + 1);
		tracker.recordSpawn(50, GOBLIN, NAME, LUMBRIDGE, NOW);
		tracker.markSaved();

		tracker.forgetArea(AREA);

		assertFalse(tracker.isHidden(50, GOBLIN));
		assertEquals(0, tracker.kills(AREA));
		assertEquals(0, tracker.hiddenHere(AREA));
		tracker.setCurrentWorld(WORLD);
		assertFalse(tracker.isHidden(7, GOBLIN));
		assertTrue(tracker.isHidden(8, 2));
		assertEquals(1, tracker.killsByArea().size());
		assertTrue(tracker.isDirty());
	}

	@Test
	public void killsInRegionListsOnlyThatRegion()
	{
		kill(7);
		tracker.countKill(8, 2, "Cow", LUMBRIDGE + 1, NOW);

		assertEquals(1, tracker.killsInRegion(LUMBRIDGE).size());
		assertEquals(Integer.valueOf(1), tracker.killsInRegion(LUMBRIDGE).get(NAME));
	}

	@Test
	public void clearAllForgetsEverything()
	{
		kill(7);
		tracker.markSaved();

		tracker.clearAll();

		assertFalse(tracker.isHidden(7, GOBLIN));
		assertEquals(0, tracker.totalKills());
		assertTrue(tracker.isDirty());
		assertTrue(tracker.toSaved().isEmpty());
	}

	@Test
	public void areaKeyRoundTrips()
	{
		assertEquals(AREA, AreaKey.parse(AREA.serialize()));
		assertEquals(new AreaKey("Monk of Zamorak", 1), AreaKey.parse("1/Monk of Zamorak"));
		assertNull(AreaKey.parse("garbage"));
		assertNull(AreaKey.parse("12850/"));
		assertNull(AreaKey.parse("x/Goblin"));
	}
}

package com.npcpermadeath;

import net.runelite.api.Model;
import net.runelite.api.Node;
import net.runelite.api.TileItem;

/** Minimal ground item for tests; only id and ownership matter to the plugin. */
class FakeTileItem implements TileItem
{
	private final int id;
	private final int ownership;

	FakeTileItem(int id, int ownership)
	{
		this.id = id;
		this.ownership = ownership;
	}

	@Override
	public int getId()
	{
		return id;
	}

	@Override
	public int getOwnership()
	{
		return ownership;
	}

	@Override
	public int getQuantity()
	{
		return 1;
	}

	@Override
	public int getVisibleTime()
	{
		return 0;
	}

	@Override
	public int getDespawnTime()
	{
		return 0;
	}

	@Override
	public boolean isPrivate()
	{
		return ownership == OWNERSHIP_SELF;
	}

	@Override
	public Model getModel()
	{
		return null;
	}

	@Override
	public int getModelHeight()
	{
		return 0;
	}

	@Override
	public void setModelHeight(int height)
	{
	}

	@Override
	public int getAnimationHeightOffset()
	{
		return 0;
	}

	@Override
	public int getRenderMode()
	{
		return 0;
	}

	@Override
	public Node getNext()
	{
		return null;
	}

	@Override
	public Node getPrevious()
	{
		return null;
	}

	@Override
	public long getHash()
	{
		return id;
	}
}

package com.npcpermadeath;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.npcpermadeath.SpawnLearner.SpawnTile;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.zip.GZIPOutputStream;
import org.junit.Test;

public class SpawnLearnerTest
{
	private static final int GOBLIN = 3029;
	private static final int LUMBRIDGE = 12850;

	private final SpawnLearner learner = new SpawnLearner();

	private static byte[] gzip(String text) throws IOException
	{
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (GZIPOutputStream out = new GZIPOutputStream(bytes))
		{
			out.write(text.getBytes(StandardCharsets.UTF_8));
		}
		return bytes.toByteArray();
	}

	@Test
	public void respawnOfADeadNpcTeachesItsTile()
	{
		learner.noteDeath(7, GOBLIN, "Goblin", 100);

		SpawnTile tile = learner.noteSpawn(7, GOBLIN, "Goblin", 3245, 3245, 0, 130, true);

		assertNotNull(tile);
		assertEquals(LUMBRIDGE, tile.region());
		assertEquals(1, learner.countInRegion("Goblin", LUMBRIDGE));
		assertEquals(Collections.singleton("Goblin"), learner.namesInRegion(LUMBRIDGE));
		assertTrue(learner.hasSpawns(LUMBRIDGE));
		assertFalse(learner.hasSpawns(LUMBRIDGE + 1));
		assertTrue(learner.isDirty());
	}

	@Test
	public void spawnsThatAreNotARespawnTeachNothing()
	{
		assertNull(learner.noteSpawn(7, GOBLIN, "Goblin", 3245, 3245, 0, 130, true));

		learner.noteDeath(7, GOBLIN, "Goblin", 100);
		assertNull(learner.noteSpawn(7, GOBLIN, "Goblin", 3245, 3245, 0, 130, false));

		learner.noteDeath(8, GOBLIN, "Goblin", 100);
		assertNull(learner.noteSpawn(8, 9999, "Cow", 3245, 3245, 0, 130, true));

		learner.noteDeath(9, GOBLIN, "Goblin", 100);
		assertNull(learner.noteSpawn(9, GOBLIN, "Goblin", 3245, 3245, 0, 100 + SpawnLearner.RESPAWN_TTL_TICKS + 1, true));
		assertEquals(0, learner.learnedCount());
	}

	@Test
	public void oneDeathTeachesAtMostOnce()
	{
		learner.noteDeath(7, GOBLIN, "Goblin", 100);
		learner.noteSpawn(7, GOBLIN, "Goblin", 3245, 3245, 0, 130, true);

		assertNull(learner.noteSpawn(7, GOBLIN, "Goblin", 3246, 3245, 0, 131, true));
	}

	@Test
	public void sameTileIsNotLearnedTwice()
	{
		learner.noteDeath(7, GOBLIN, "Goblin", 100);
		learner.noteSpawn(7, GOBLIN, "Goblin", 3245, 3245, 0, 130, true);
		learner.noteDeath(7, GOBLIN, "Goblin", 200);

		assertNull(learner.noteSpawn(7, GOBLIN, "Goblin", 3245, 3245, 0, 230, true));
		assertEquals(1, learner.learnedCount());
	}

	@Test
	public void seedAndLearnedTilesAreCountedOnce() throws IOException
	{
		learner.loadSeed(new ByteArrayInputStream(gzip(
			"# header\nGoblin|3029|3245|3245|0\nGoblin|3029|3250|3230|0\nRat|2854|3210|3210|0\nbad line\n")));
		assertEquals(3, learner.seedCount());
		learner.noteDeath(7, GOBLIN, "Goblin", 100);
		learner.noteSpawn(7, GOBLIN, "Goblin", 3250, 3230, 0, 130, true);
		learner.noteDeath(8, GOBLIN, "Goblin", 100);
		learner.noteSpawn(8, GOBLIN, "Goblin", 3260, 3240, 0, 130, true);

		assertEquals(3, learner.countInRegion("Goblin", LUMBRIDGE));
		assertEquals(1, learner.countInRegion("Rat", LUMBRIDGE));
		assertEquals(0, learner.countInRegion("Cow", LUMBRIDGE));
		assertEquals(Arrays.asList("Goblin", "Rat"), new java.util.ArrayList<>(learner.namesInRegion(LUMBRIDGE)));
		assertEquals(2, learner.learnedCount());
	}

	@Test
	public void stateRoundTripsThroughText()
	{
		learner.noteDeath(7, GOBLIN, "Goblin", 100);
		learner.noteSpawn(7, GOBLIN, "Goblin", 3245, 3245, 0, 130, true);

		SpawnLearner fresh = new SpawnLearner();
		fresh.load(learner.serializeLearned());

		assertEquals(1, fresh.learnedCount());
		assertEquals(1, fresh.countInRegion("Goblin", LUMBRIDGE));
		assertEquals("Goblin|3029|3245|3245|0", learner.serializeLearned().get(0));
		assertNull(SpawnTile.parse("garbage"));
		assertNull(SpawnTile.parse("|1|2|3|4"));
		assertNull(SpawnTile.parse("Goblin|a|b|c|d"));
		fresh.load(Arrays.asList("bad", "Rat|2854|3200|3200|0"));
		assertEquals(1, fresh.learnedCount());
	}

	@Test
	public void staleDeathsArePruned()
	{
		learner.noteDeath(7, GOBLIN, "Goblin", 100);
		learner.prune(100 + SpawnLearner.RESPAWN_TTL_TICKS + 1);

		assertNull(learner.noteSpawn(7, GOBLIN, "Goblin", 3245, 3245, 0, 130, true));
	}
}

package com.npcpermadeath;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.List;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The list for the chunk the mouse is over on the world map, pinned beside
 * the chunk. Drawn above every widget so map markers cannot cover it.
 */
class ChunkPanelOverlay extends Overlay
{
	private static final int MAX_PANEL_LINES = 30;
	private static final int PANEL_GAP = 8;
	private static final Color UNTOUCHED = new Color(170, 170, 170);

	private final ChunkMapOverlay mapOverlay;
	private final PanelComponent panel = new PanelComponent();

	ChunkPanelOverlay(NpcPermadeathPlugin plugin, ChunkMapOverlay mapOverlay)
	{
		super(plugin);
		this.mapOverlay = mapOverlay;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		panel.setBackgroundColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		int region = mapOverlay.getHoveredRegion();
		Rectangle chunk = mapOverlay.getHoveredRect();
		Rectangle bounds = mapOverlay.getMapBounds();
		if (region < 0 || chunk == null || bounds == null)
		{
			return null;
		}
		ChunkMapOverlay.ChunkSource source = mapOverlay.getSource();
		panel.getChildren().clear();
		panel.getChildren().add(TitleComponent.builder().text(source.heading(region)).color(Color.WHITE).build());
		List<ChunkMapOverlay.Entry> entries = source.entries(region);
		int shown = Math.min(entries.size(), MAX_PANEL_LINES);
		for (int i = 0; i < shown; i++)
		{
			ChunkMapOverlay.Entry e = entries.get(i);
			String count = e.getTotal() == null ? Integer.toString(e.getKills()) : e.getKills() + " / " + e.getTotal();
			Color color = e.getKills() == 0 ? UNTOUCHED
				: e.getTotal() != null && e.getKills() >= e.getTotal()
					? ChunkMapOverlay.State.ALL.color
					: ChunkMapOverlay.State.SOME.color;
			panel.getChildren().add(LineComponent.builder()
				.left(e.getName()).leftColor(e.getKills() == 0 ? UNTOUCHED : Color.WHITE)
				.right(count).rightColor(color)
				.build());
		}
		if (entries.size() > shown)
		{
			panel.getChildren().add(LineComponent.builder().left("+" + (entries.size() - shown) + " more").build());
		}

		// Measure first with an empty clip, then place beside the chunk and draw for real.
		Shape clip = g.getClip();
		g.setClip(new Rectangle(0, 0, 0, 0));
		panel.setPreferredLocation(new java.awt.Point(0, 0));
		Dimension size = panel.render(g);
		g.setClip(clip);
		if (size == null)
		{
			return null;
		}
		int x = chunk.x + chunk.width + PANEL_GAP;
		if (x + size.width > bounds.x + bounds.width)
		{
			x = chunk.x - PANEL_GAP - size.width;
		}
		int y = Math.max(bounds.y, Math.min(chunk.y, bounds.y + bounds.height - size.height));
		panel.setPreferredLocation(new java.awt.Point(x, y));
		panel.render(g);
		return null;
	}
}

