package com.npcpermadeath;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.List;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Outlines map chunks on the world map: green where nothing has been
 * killed, orange where something has, red where every NPC type is gone.
 * Hovering a chunk shows every NPC type in it with kills and totals in a
 * panel pinned beside the chunk, so it stays clear of the map's own
 * tooltips.
 */
class ChunkMapOverlay extends Overlay
{
	static final int CHUNK_TILES = 64;

	enum State
	{
		NONE(new Color(70, 200, 90, 110), 1f),
		SOME(new Color(255, 160, 40, 230), 2f),
		ALL(new Color(235, 50, 50, 240), 2f);

		final Color color;
		final float stroke;

		State(Color color, float stroke)
		{
			this.color = color;
			this.stroke = stroke;
		}
	}

	/** One NPC type in a chunk. */
	@Value
	static class Entry
	{
		String name;
		int kills;
		/** Known spawns, or null. */
		Integer total;
	}

	/** What the plugin knows about chunks; called on the client thread while rendering. */
	interface ChunkSource
	{
		boolean isKnown(int region);

		State state(int region);

		String heading(int region);

		List<Entry> entries(int region);
	}

	/** Beyond this many chunks in view, only chunks with kills are drawn. */
	private static final int MAX_FULL_GRID = 2500;

	private final Client client;
	private final ChunkSource source;
	/** Chunk under the mouse this frame, or -1; read by {@link ChunkPanelOverlay}. */
	private int hoveredRegion = -1;
	private Rectangle hoveredRect;
	private Rectangle mapBounds;

	ChunkMapOverlay(NpcPermadeathPlugin plugin, Client client, ChunkSource source)
	{
		super(plugin);
		this.client = client;
		this.source = source;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.Worldmap.MAP_CONTAINER >>> 16);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		hoveredRegion = -1;
		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map == null || map.isHidden())
		{
			return null;
		}
		Rectangle bounds = map.getBounds();
		WorldMap worldMap = client.getWorldMap();
		Point centre = worldMap.getWorldMapPosition();
		double pxPerTile = worldMap.getWorldMapZoom();
		if (centre == null || pxPerTile <= 0)
		{
			return null;
		}
		mapBounds = bounds;
		// The map widget's centre shows the world tile the map is positioned on.
		double originX = bounds.getCenterX() - centre.getX() * pxPerTile;
		double originY = bounds.getCenterY() + centre.getY() * pxPerTile;
		// World tile range currently on screen (y grows upward on the map).
		int minTileX = (int) Math.floor((bounds.x - originX) / pxPerTile);
		int maxTileX = (int) Math.ceil((bounds.x + bounds.width - originX) / pxPerTile);
		int minTileY = (int) Math.floor((originY - (bounds.y + bounds.height)) / pxPerTile);
		int maxTileY = (int) Math.ceil((originY - bounds.y) / pxPerTile);
		int rx0 = Math.max(0, minTileX >> 6);
		int rx1 = Math.min(255, maxTileX >> 6);
		int ry0 = Math.max(0, minTileY >> 6);
		int ry1 = Math.min(255, maxTileY >> 6);
		boolean fullGrid = (long) (rx1 - rx0 + 1) * (ry1 - ry0 + 1) <= MAX_FULL_GRID;

		Shape oldClip = g.getClip();
		g.setClip(bounds);
		Point mouse = client.getMouseCanvasPosition();
		int hovered = -1;
		Rectangle hoveredRect = null;
		for (int rx = rx0; rx <= rx1; rx++)
		{
			for (int ry = ry0; ry <= ry1; ry++)
			{
				int region = (rx << 8) | ry;
				if (!source.isKnown(region))
				{
					continue;
				}
				State state = source.state(region);
				if (!fullGrid && state == State.NONE)
				{
					continue;
				}
				int px = (int) Math.round(originX + (rx << 6) * pxPerTile);
				int py = (int) Math.round(originY - ((ry << 6) + CHUNK_TILES) * pxPerTile);
				int size = (int) Math.round(CHUNK_TILES * pxPerTile);
				Rectangle rect = new Rectangle(px, py, size, size);
				if (!rect.intersects(bounds))
				{
					continue;
				}
				g.setColor(state.color);
				g.setStroke(new BasicStroke(state.stroke));
				g.draw(rect);
				if (mouse != null && bounds.contains(mouse.getX(), mouse.getY()) && rect.contains(mouse.getX(), mouse.getY()))
				{
					hovered = region;
					hoveredRect = rect;
				}
			}
		}
		if (hovered >= 0)
		{
			g.setColor(Color.WHITE);
			g.setStroke(new BasicStroke(2f));
			g.draw(hoveredRect);
			this.hoveredRegion = hovered;
			this.hoveredRect = hoveredRect;
		}
		g.setClip(oldClip);
		return null;
	}

	int getHoveredRegion()
	{
		return hoveredRegion;
	}

	Rectangle getHoveredRect()
	{
		return hoveredRect;
	}

	Rectangle getMapBounds()
	{
		return mapBounds;
	}

	ChunkSource getSource()
	{
		return source;
	}
}

package com.npcpermadeath;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * What the OSRS Wiki knows about an NPC's spawns: how many there are per map
 * region and what the wiki calls that place ("Lumbridge"). Parsed from the
 * location lines on the NPC's page, fetched once per NPC name and cached in
 * the client config for a week. Display only; hiding works without it.
 */
@Slf4j
class SpawnTotals
{
	static final String KEY = "spawnTotals";
	static final long TTL_MS = 7L * 24 * 60 * 60 * 1000;
	private static final HttpUrl WIKI = HttpUrl.parse("https://oldschool.runescape.wiki/w/");
	private static final Type CACHE_TYPE = new TypeToken<Map<String, Cached>>()
	{
	}.getType();
	private static final Pattern PIN = Pattern.compile("x:\\s*(-?\\d+)\\s*,\\s*y:\\s*(-?\\d+)");
	private static final Pattern REDIRECT = Pattern.compile("^\\s*#REDIRECT\\s*\\[\\[([^\\]|]+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern LINK = Pattern.compile("\\[\\[([^\\]|]*)(?:\\|([^\\]]*))?\\]\\]");
	private static final int MAX_REDIRECTS = 2;

	static class Cached
	{
		long fetched;
		Map<Integer, Integer> byRegion = new HashMap<>();
		Map<Integer, String> labelByRegion = new HashMap<>();
	}

	/** Spawn counts and place names for one NPC page. */
	static class PageSpawns
	{
		final Map<Integer, Integer> byRegion = new HashMap<>();
		/** region -> place label -> pins with that label */
		final Map<Integer, Map<String, Integer>> labelVotes = new HashMap<>();

		Map<Integer, String> labels()
		{
			Map<Integer, String> out = new HashMap<>();
			labelVotes.forEach((region, votes) -> votes.entrySet().stream()
				.max(Map.Entry.comparingByValue())
				.ifPresent(e -> out.put(region, e.getKey())));
			return out;
		}
	}

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ConfigManager configManager;
	private final ClientThread clientThread;

	private final Map<String, Cached> cache = new HashMap<>();
	private final Set<String> inFlight = new HashSet<>();
	/** Best known place name per region, pooled from every fetched NPC. */
	private final Map<Integer, String> regionLabels = new HashMap<>();

	SpawnTotals(OkHttpClient httpClient, Gson gson, ConfigManager configManager, ClientThread clientThread)
	{
		this.httpClient = httpClient;
		this.gson = gson;
		this.configManager = configManager;
		this.clientThread = clientThread;
	}

	void load()
	{
		cache.clear();
		regionLabels.clear();
		String json = configManager.getConfiguration(NpcPermadeathConfig.GROUP, KEY);
		if (json == null)
		{
			return;
		}
		try
		{
			Map<String, Cached> stored = gson.fromJson(json, CACHE_TYPE);
			if (stored != null)
			{
				stored.forEach((name, cached) ->
				{
					// Entries without labels come from an older format; drop them so they are fetched again.
					if (cached != null && cached.byRegion != null && cached.labelByRegion != null)
					{
						cache.put(name, cached);
						regionLabels.putAll(cached.labelByRegion);
					}
				});
			}
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Discarding unreadable spawn totals cache", e);
		}
	}

	private void save()
	{
		configManager.setConfiguration(NpcPermadeathConfig.GROUP, KEY, gson.toJson(cache, CACHE_TYPE));
	}

	/**
	 * @return the number of spawns of this NPC in the region, or null if unknown
	 */
	Integer get(String name, int region)
	{
		Cached cached = cache.get(name);
		return cached == null ? null : cached.byRegion.get(region);
	}

	/** A place name for the region, preferring this NPC's own page, or null if unknown. */
	String label(String name, int region)
	{
		Cached cached = cache.get(name);
		if (cached != null)
		{
			String own = cached.labelByRegion.get(region);
			if (own != null)
			{
				return own;
			}
		}
		return regionLabels.get(region);
	}

	boolean isKnown(String name)
	{
		return cache.containsKey(name);
	}

	/** Stores parsed page data directly; used by tests and by the fetch callback. */
	void put(String name, PageSpawns spawns, long now)
	{
		Cached fresh = new Cached();
		fresh.fetched = now;
		fresh.byRegion = spawns.byRegion;
		fresh.labelByRegion = spawns.labels();
		cache.put(name, fresh);
		regionLabels.putAll(fresh.labelByRegion);
	}

	/** Fetches the NPC's page if missing or stale; runs the callback on the client thread when done. */
	void ensure(String name, long now, Runnable onLoaded)
	{
		Cached cached = cache.get(name);
		if (cached != null && now - cached.fetched < TTL_MS)
		{
			return;
		}
		if (!inFlight.add(name))
		{
			return;
		}
		fetch(name, name, 0, now, onLoaded);
	}

	private void fetch(String name, String title, int redirects, long now, Runnable onLoaded)
	{
		HttpUrl url = WIKI.newBuilder().addPathSegment(title).addQueryParameter("action", "raw").build();
		httpClient.newCall(new Request.Builder().url(url).build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Spawn lookup failed for {}", name, e);
				clientThread.invoke(() -> inFlight.remove(name));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				String body = null;
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						body = r.body().string();
					}
					else if (r.code() == 404)
					{
						body = "";
					}
				}
				catch (IOException | RuntimeException e)
				{
					log.debug("Could not read spawn page for {}", name, e);
				}
				if (body != null)
				{
					Matcher redirect = REDIRECT.matcher(body);
					if (redirect.find() && redirects < MAX_REDIRECTS)
					{
						fetch(name, redirect.group(1).trim(), redirects + 1, now, onLoaded);
						return;
					}
				}
				PageSpawns result = body == null ? null : parse(body);
				clientThread.invoke(() ->
				{
					inFlight.remove(name);
					if (result == null)
					{
						return;
					}
					put(name, result, now);
					save();
					onLoaded.run();
				});
			}
		});
	}

	/**
	 * Reads every {@code {{LocLine ...}}} on a wiki page. A page without any
	 * (or an empty body for a missing page) yields empty maps, which are still
	 * cached so the lookup is not repeated.
	 */
	static PageSpawns parse(String wikitext)
	{
		PageSpawns spawns = new PageSpawns();
		int from = 0;
		while (true)
		{
			int start = wikitext.indexOf("{{LocLine", from);
			if (start < 0)
			{
				break;
			}
			int end = templateEnd(wikitext, start);
			if (end < 0)
			{
				break;
			}
			parseLocLine(wikitext.substring(start + 2, end), spawns);
			from = end + 2;
		}
		return spawns;
	}

	/** Index of the {@code }}} closing the template opened at {@code start}, or -1. */
	private static int templateEnd(String text, int start)
	{
		int depth = 0;
		for (int i = start; i + 1 < text.length(); i++)
		{
			if (text.charAt(i) == '{' && text.charAt(i + 1) == '{')
			{
				depth++;
				i++;
			}
			else if (text.charAt(i) == '}' && text.charAt(i + 1) == '}')
			{
				depth--;
				if (depth == 0)
				{
					return i;
				}
				i++;
			}
		}
		return -1;
	}

	private static void parseLocLine(String body, PageSpawns spawns)
	{
		String location = null;
		int mapId = 0;
		Map<Integer, Integer> pins = new TreeMap<>();
		for (String part : splitParams(body))
		{
			String p = part.trim();
			int eq = p.indexOf('=');
			if (eq > 0)
			{
				String key = p.substring(0, eq).trim();
				String value = p.substring(eq + 1).trim();
				if (key.equals("location"))
				{
					location = cleanLabel(value);
				}
				else if (key.equals("mapID"))
				{
					try
					{
						mapId = Integer.parseInt(value);
					}
					catch (NumberFormatException ignored)
					{
						mapId = -1;
					}
				}
				continue;
			}
			Matcher pin = PIN.matcher(p);
			while (pin.find())
			{
				int x = Integer.parseInt(pin.group(1));
				int y = Integer.parseInt(pin.group(2));
				pins.merge(((x >> 6) << 8) | (y >> 6), 1, Integer::sum);
			}
		}
		if (mapId != 0)
		{
			return;
		}
		for (Map.Entry<Integer, Integer> e : pins.entrySet())
		{
			spawns.byRegion.merge(e.getKey(), e.getValue(), Integer::sum);
			if (location != null && !location.isEmpty())
			{
				spawns.labelVotes.computeIfAbsent(e.getKey(), r -> new HashMap<>())
					.merge(location, e.getValue(), Integer::sum);
			}
		}
	}

	/** Splits template parameters on {@code |}, ignoring pipes inside links and nested templates. */
	static java.util.List<String> splitParams(String body)
	{
		java.util.List<String> parts = new java.util.ArrayList<>();
		StringBuilder current = new StringBuilder();
		int depth = 0;
		for (int i = 0; i < body.length(); i++)
		{
			char ch = body.charAt(i);
			char next = i + 1 < body.length() ? body.charAt(i + 1) : '\0';
			if ((ch == '[' && next == '[') || (ch == '{' && next == '{'))
			{
				depth++;
				current.append(ch).append(next);
				i++;
			}
			else if ((ch == ']' && next == ']') || (ch == '}' && next == '}'))
			{
				depth = Math.max(0, depth - 1);
				current.append(ch).append(next);
				i++;
			}
			else if (ch == '|' && depth == 0)
			{
				parts.add(current.toString());
				current.setLength(0);
			}
			else
			{
				current.append(ch);
			}
		}
		parts.add(current.toString());
		return parts;
	}

	/** Turns wiki markup like {@code [[Lumbridge Swamp|the swamp]]} into plain text. */
	static String cleanLabel(String value)
	{
		Matcher m = LINK.matcher(value);
		StringBuffer sb = new StringBuffer();
		while (m.find())
		{
			String shown = m.group(2) != null ? m.group(2) : m.group(1);
			m.appendReplacement(sb, Matcher.quoteReplacement(shown));
		}
		m.appendTail(sb);
		return sb.toString()
			.replaceAll("\\{\\{[^}]*\\}\\}", "")
			.replace("'''", "")
			.replace("''", "")
			.replaceAll("<[^>]*>", "")
			.replaceAll("\\s+", " ")
			.trim();
	}
}

package com.npcpermadeath;

import lombok.Value;

/**
 * One NPC type in one map region (a 64x64 tile chunk). Kill counts are kept
 * per area so that killing goblins in Lumbridge does not hide goblins in the
 * Goblin Village.
 */
@Value
public class AreaKey
{
	String name;
	int region;

	String serialize()
	{
		return region + "/" + name;
	}

	/**
	 * @return the parsed key, or null when the text is not a serialized key
	 */
	static AreaKey parse(String text)
	{
		int slash = text.indexOf('/');
		if (slash <= 0 || slash == text.length() - 1)
		{
			return null;
		}
		try
		{
			return new AreaKey(text.substring(slash + 1), Integer.parseInt(text.substring(0, slash)));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.npcpermadeath;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import lombok.Value;

/**
 * Pure bookkeeping for which NPCs should be hidden. Knows nothing about the
 * client so it can be unit tested.
 *
 * <p>The authoritative record is a <em>kill count</em> per NPC type per map
 * region. The plugin then keeps exactly that many NPCs of that type hidden in
 * the region. It prefers the individuals that were actually killed, which it
 * recognises by the server's NPC index (kept across death and respawn on one
 * world), and when those cannot be found, for example on another world, it
 * substitutes other NPCs of the same type as they come into view. Hidden
 * choices are sticky so the same NPCs stay hidden as you move around.
 */
class PermadeathTracker
{
	/** A death older than this is forgotten if the NPC never despawned. */
	static final int PENDING_TTL_TICKS = 6000;
	/** A hidden record not seen for this long is dropped so counts self-heal. */
	static final long RECORD_TTL_MS = 14L * 24 * 60 * 60 * 1000;

	enum SpawnOutcome
	{
		VISIBLE,
		/** Hidden because this is an NPC that was recorded hidden before. */
		EXACT,
		/** Hidden to bring the area up to its kill count. */
		SUBSTITUTE
	}

	/** One hidden NPC on one world. Plain fields so Gson can persist it. */
	static class HiddenNpc
	{
		int index;
		int npcId;
		int world;
		String name;
		int region;
		long lastSeen;

		HiddenNpc()
		{
		}

		HiddenNpc(int index, int npcId, int world, String name, int region, long lastSeen)
		{
			this.index = index;
			this.npcId = npcId;
			this.world = world;
			this.name = name;
			this.region = region;
			this.lastSeen = lastSeen;
		}

		AreaKey area()
		{
			return new AreaKey(name, region);
		}
	}

	/** Everything that is persisted. */
	static class SavedState
	{
		Map<String, Integer> kills = new TreeMap<>();
		List<HiddenNpc> hidden = new ArrayList<>();

		boolean isEmpty()
		{
			return kills.isEmpty() && hidden.isEmpty();
		}
	}

	@Value
	static class PendingDeath
	{
		int npcId;
		String name;
		int region;
		int tick;
	}

	/** Damage dealt to an NPC by the player and by everyone else. */
	static class DamageTally
	{
		int mine;
		int others;
		boolean firstHitMine;
	}

	private final Map<Integer, DamageTally> damage = new HashMap<>();
	private final Map<Integer, PendingDeath> pending = new HashMap<>();

	private final Map<AreaKey, Integer> kills = new HashMap<>();
	/** world -> index -> record */
	private final Map<Integer, Map<Integer, HiddenNpc>> hidden = new HashMap<>();
	/** Hidden records on the current world, counted per area. */
	private final Map<AreaKey, Integer> hiddenHere = new HashMap<>();

	private int currentWorld = -1;
	private boolean dirty;

	void setCurrentWorld(int world)
	{
		currentWorld = world;
		hiddenHere.clear();
		for (HiddenNpc rec : here().values())
		{
			hiddenHere.merge(rec.area(), 1, Integer::sum);
		}
	}

	private Map<Integer, HiddenNpc> here()
	{
		return hidden.computeIfAbsent(currentWorld, w -> new HashMap<>());
	}

	void recordHit(int index, int amount, boolean mine)
	{
		DamageTally tally = damage.get(index);
		if (tally == null)
		{
			tally = new DamageTally();
			tally.firstHitMine = mine;
			damage.put(index, tally);
		}
		if (mine)
		{
			tally.mine += amount;
		}
		else
		{
			tally.others += amount;
		}
	}

	/**
	 * Whether the kill would be the player's by the game's loot rule: most
	 * damage dealt, ties going to whoever hit first.
	 */
	boolean isMyKill(int index)
	{
		DamageTally tally = damage.get(index);
		if (tally == null || tally.mine == 0)
		{
			return false;
		}
		return tally.mine > tally.others || (tally.mine == tally.others && tally.firstHitMine);
	}

	/** Marks an NPC as dying; the death is taken for a decision when it despawns. */
	void recordDeath(int index, int npcId, String name, int region, int tick)
	{
		pending.put(index, new PendingDeath(npcId, name, region, tick));
	}

	boolean isPending(int index)
	{
		return pending.containsKey(index);
	}

	/**
	 * Takes the pending death for a despawning NPC so the caller can decide
	 * whether it counts.
	 *
	 * @return the death, or null if this NPC was not dying
	 */
	PendingDeath takeDeath(int index, int npcId)
	{
		PendingDeath death = pending.get(index);
		if (death == null || death.getNpcId() != npcId)
		{
			return null;
		}
		pending.remove(index);
		return death;
	}

	/** Drops everything in flight for an NPC that left without being counted. */
	void forget(int index)
	{
		damage.remove(index);
		pending.remove(index);
	}

	/**
	 * Counts a kill and hides the NPC.
	 *
	 * @return the area the kill was counted in, or null if it was already hidden
	 */
	AreaKey countKill(int index, int npcId, String name, int region, long now)
	{
		damage.remove(index);
		HiddenNpc existing = here().get(index);
		if (existing != null)
		{
			// It was already one of ours (hidden and killed again, e.g. by a cannon).
			existing.lastSeen = now;
			return null;
		}
		AreaKey key = new AreaKey(name, region);
		kills.merge(key, 1, Integer::sum);
		put(new HiddenNpc(index, npcId, currentWorld, name, region, now));
		dirty = true;
		return key;
	}

	SpawnOutcome recordSpawn(int index, int npcId, String name, int region, long now)
	{
		HiddenNpc rec = here().get(index);
		if (rec != null)
		{
			if (rec.npcId == npcId)
			{
				rec.lastSeen = now;
				return SpawnOutcome.EXACT;
			}
			// Same world, same index, different NPC: the server renumbered.
			remove(index);
			dirty = true;
		}
		AreaKey key = new AreaKey(name, region);
		int wanted = kills.getOrDefault(key, 0);
		if (wanted == 0)
		{
			return SpawnOutcome.VISIBLE;
		}
		if (hiddenHere.getOrDefault(key, 0) < wanted)
		{
			put(new HiddenNpc(index, npcId, currentWorld, name, region, now));
			dirty = true;
			return SpawnOutcome.SUBSTITUTE;
		}
		return SpawnOutcome.VISIBLE;
	}

	private void put(HiddenNpc rec)
	{
		HiddenNpc previous = here().put(rec.index, rec);
		if (previous != null)
		{
			decrement(previous.area());
		}
		hiddenHere.merge(rec.area(), 1, Integer::sum);
	}

	private void remove(int index)
	{
		HiddenNpc previous = here().remove(index);
		if (previous != null)
		{
			decrement(previous.area());
		}
	}

	private void decrement(AreaKey key)
	{
		hiddenHere.computeIfPresent(key, (k, n) -> n <= 1 ? null : n - 1);
	}

	boolean isHidden(int index, int npcId)
	{
		HiddenNpc rec = here().get(index);
		return rec != null && rec.npcId == npcId;
	}

	/**
	 * Makes a hidden NPC visible again, for example because it is attacking
	 * the player. The kill count is untouched, so the area now has a deficit
	 * that {@link #recordSpawn} fills from the next eligible NPC.
	 *
	 * @return the area that now has a deficit, or null if it was not hidden
	 */
	AreaKey release(int index)
	{
		HiddenNpc rec = here().get(index);
		if (rec == null)
		{
			return null;
		}
		remove(index);
		dirty = true;
		return rec.area();
	}

	boolean hasDeficit(AreaKey key)
	{
		return hiddenHere(key) < kills(key);
	}

	int kills(AreaKey key)
	{
		return kills.getOrDefault(key, 0);
	}

	int hiddenHere(AreaKey key)
	{
		return hiddenHere.getOrDefault(key, 0);
	}

	int totalKills()
	{
		return kills.values().stream().mapToInt(Integer::intValue).sum();
	}

	/** A snapshot of every kill count. */
	Map<AreaKey, Integer> killsByArea()
	{
		return new HashMap<>(kills);
	}

	/**
	 * Moves an area's kills and hidden records into another region of the
	 * same NPC, for kills recorded in a chunk the NPC does not spawn in.
	 */
	void rehome(AreaKey from, int toRegion)
	{
		if (from.getRegion() == toRegion)
		{
			return;
		}
		Integer moved = kills.remove(from);
		if (moved == null)
		{
			return;
		}
		AreaKey to = new AreaKey(from.getName(), toRegion);
		kills.merge(to, moved, Integer::sum);
		for (Map<Integer, HiddenNpc> world : hidden.values())
		{
			for (HiddenNpc rec : world.values())
			{
				if (rec.area().equals(from))
				{
					rec.region = toRegion;
				}
			}
		}
		setCurrentWorld(currentWorld);
		dirty = true;
	}

	/**
	 * Moves some of an area's kills, and as many of its hidden records, into
	 * another region of the same NPC. Used when a chunk has more kills than
	 * spawns: the extra NPCs must have wandered in from next door.
	 *
	 * @return how many kills were moved
	 */
	int moveKills(AreaKey from, int toRegion, int count)
	{
		int available = kills(from);
		int n = Math.min(count, available);
		if (n <= 0 || from.getRegion() == toRegion)
		{
			return 0;
		}
		AreaKey to = new AreaKey(from.getName(), toRegion);
		if (n == available)
		{
			kills.remove(from);
		}
		else
		{
			kills.put(from, available - n);
		}
		kills.merge(to, n, Integer::sum);
		for (Map<Integer, HiddenNpc> world : hidden.values())
		{
			int moved = 0;
			for (HiddenNpc rec : world.values())
			{
				if (moved >= n)
				{
					break;
				}
				if (rec.area().equals(from))
				{
					rec.region = toRegion;
					moved++;
				}
			}
		}
		setCurrentWorld(currentWorld);
		dirty = true;
		return n;
	}

	/** Drops the kill count for one NPC in one area and brings its hidden NPCs back on every world. */
	void forgetArea(AreaKey key)
	{
		if (kills.remove(key) == null)
		{
			return;
		}
		for (Map<Integer, HiddenNpc> world : hidden.values())
		{
			world.values().removeIf(rec -> rec.area().equals(key));
		}
		hiddenHere.remove(key);
		dirty = true;
	}

	/** Kill counts for every NPC type in one region, sorted by name. */
	Map<String, Integer> killsInRegion(int region)
	{
		Map<String, Integer> out = new TreeMap<>();
		kills.forEach((key, n) ->
		{
			if (key.getRegion() == region)
			{
				out.put(key.getName(), n);
			}
		});
		return out;
	}

	/** Drops deaths whose NPC never despawned and hidden records gone stale. */
	void prune(int tick, long now)
	{
		pending.values().removeIf(d -> tick - d.getTick() > PENDING_TTL_TICKS);
		for (Map.Entry<Integer, Map<Integer, HiddenNpc>> world : hidden.entrySet())
		{
			Iterator<HiddenNpc> it = world.getValue().values().iterator();
			while (it.hasNext())
			{
				HiddenNpc rec = it.next();
				if (now - rec.lastSeen > RECORD_TTL_MS)
				{
					it.remove();
					dirty = true;
					if (world.getKey() == currentWorld)
					{
						decrement(rec.area());
					}
				}
			}
		}
	}

	/** Forgets in-flight state that only means something on one world. */
	void clearSession()
	{
		damage.clear();
		pending.clear();
	}

	void clearAll()
	{
		clearSession();
		kills.clear();
		hidden.clear();
		hiddenHere.clear();
		dirty = true;
	}

	boolean isDirty()
	{
		return dirty;
	}

	void markSaved()
	{
		dirty = false;
	}

	SavedState toSaved()
	{
		SavedState state = new SavedState();
		kills.forEach((key, n) -> state.kills.put(key.serialize(), n));
		for (Map<Integer, HiddenNpc> world : hidden.values())
		{
			state.hidden.addAll(world.values());
		}
		return state;
	}

	void load(SavedState state)
	{
		kills.clear();
		hidden.clear();
		if (state.kills != null)
		{
			state.kills.forEach((text, n) ->
			{
				AreaKey key = AreaKey.parse(text);
				if (key != null && n != null && n > 0)
				{
					kills.put(key, n);
				}
			});
		}
		if (state.hidden != null)
		{
			for (HiddenNpc rec : state.hidden)
			{
				if (rec != null && rec.name != null)
				{
					hidden.computeIfAbsent(rec.world, w -> new HashMap<>()).put(rec.index, rec);
				}
			}
		}
		dirty = false;
		setCurrentWorld(currentWorld);
	}
}

package com.npcpermadeath;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.zip.GZIPInputStream;
import lombok.Value;

/**
 * Everything known about where NPCs spawn, indexed by map chunk: a bundled
 * seed (the community spawn dump) plus tiles this client observed itself.
 *
 * <p>Observing works by watching NPCs respawn: when an NPC we saw die
 * reappears with the same index close to the player, without the player
 * having teleported, the tile it appears on is its spawn point.
 */
class SpawnLearner
{
	/** How long after a death a respawn is still recognised. */
	static final int RESPAWN_TTL_TICKS = 3000;

	@Value
	static class SpawnTile
	{
		String name;
		int npcId;
		int x;
		int y;
		int plane;

		int region()
		{
			return ((x >> 6) << 8) | (y >> 6);
		}

		String serialize()
		{
			return name + "|" + npcId + "|" + x + "|" + y + "|" + plane;
		}

		/** @return the parsed tile, or null when the text is not a serialized tile */
		static SpawnTile parse(String text)
		{
			String[] p = text.split("\\|");
			if (p.length != 5 || p[0].isEmpty())
			{
				return null;
			}
			try
			{
				return new SpawnTile(p[0], Integer.parseInt(p[1]), Integer.parseInt(p[2]), Integer.parseInt(p[3]),
					Integer.parseInt(p[4]));
			}
			catch (NumberFormatException e)
			{
				return null;
			}
		}
	}

	@Value
	private static class Dead
	{
		int npcId;
		String name;
		int tick;
	}

	private final Map<Integer, Dead> awaitingRespawn = new HashMap<>();
	/** Tiles this client observed itself. */
	private final Set<SpawnTile> learned = new HashSet<>();
	/** region -> NPC name -> every known spawn tile, from all sources. */
	private final Map<Integer, Map<String, Set<SpawnTile>>> index = new HashMap<>();
	private int seedCount;
	private boolean dirty;

	/** Loads the bundled seed: gzipped lines of name|id|x|y|plane. */
	void loadSeed(InputStream gzipped) throws IOException
	{
		try (BufferedReader reader = new BufferedReader(
			new InputStreamReader(new GZIPInputStream(gzipped), StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				SpawnTile tile = SpawnTile.parse(line);
				if (tile != null && addToIndex(tile))
				{
					seedCount++;
				}
			}
		}
	}

	private boolean addToIndex(SpawnTile tile)
	{
		return index.computeIfAbsent(tile.region(), r -> new HashMap<>())
			.computeIfAbsent(tile.getName(), n -> new HashSet<>())
			.add(tile);
	}

	void noteDeath(int index, int npcId, String name, int tick)
	{
		awaitingRespawn.put(index, new Dead(npcId, name, tick));
	}

	/**
	 * @param trustworthy whether the tile can be taken at face value (close to the player, no teleport, not in an instance)
	 * @return the newly learned tile, or null if nothing was learned
	 */
	SpawnTile noteSpawn(int index, int npcId, String name, int x, int y, int plane, int tick, boolean trustworthy)
	{
		Dead dead = awaitingRespawn.remove(index);
		if (dead == null || !trustworthy || dead.getNpcId() != npcId || tick - dead.getTick() > RESPAWN_TTL_TICKS)
		{
			return null;
		}
		SpawnTile tile = new SpawnTile(name, npcId, x, y, plane);
		if (!learned.add(tile))
		{
			return null;
		}
		addToIndex(tile);
		dirty = true;
		return tile;
	}

	/** Distinct known spawn tiles of the NPC in the chunk, seed and observed. */
	int countInRegion(String name, int region)
	{
		Map<String, Set<SpawnTile>> byName = index.get(region);
		if (byName == null)
		{
			return 0;
		}
		Set<SpawnTile> tiles = byName.get(name);
		return tiles == null ? 0 : tiles.size();
	}

	/** Every NPC type known to spawn in the chunk, sorted. */
	Set<String> namesInRegion(int region)
	{
		Map<String, Set<SpawnTile>> byName = index.get(region);
		return byName == null ? Collections.emptySet() : new TreeSet<>(byName.keySet());
	}

	boolean hasSpawns(int region)
	{
		return index.containsKey(region);
	}

	void prune(int tick)
	{
		awaitingRespawn.values().removeIf(d -> tick - d.getTick() > RESPAWN_TTL_TICKS);
	}

	void clearSession()
	{
		awaitingRespawn.clear();
	}

	int seedCount()
	{
		return seedCount;
	}

	int learnedCount()
	{
		return learned.size();
	}

	boolean isDirty()
	{
		return dirty;
	}

	void markSaved()
	{
		dirty = false;
	}

	List<String> serializeLearned()
	{
		List<String> out = new ArrayList<>();
		learned.forEach(t -> out.add(t.serialize()));
		Collections.sort(out);
		return out;
	}

	void load(Collection<String> learnedEntries)
	{
		learned.clear();
		for (String e : learnedEntries)
		{
			SpawnTile t = SpawnTile.parse(e);
			if (t != null && learned.add(t))
			{
				addToIndex(t);
			}
		}
		dirty = false;
	}
}

package com.npcpermadeath;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import lombok.Value;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/** Sidebar list of everything slain, one section per map chunk. */
class PermadeathPanel extends PluginPanel
{
	/** How far along an NPC type is, in display order. */
	enum Progress
	{
		STARTED(ColorScheme.BRAND_ORANGE),
		CLEARED(ColorScheme.PROGRESS_ERROR_COLOR),
		UNTOUCHED(ColorScheme.LIGHT_GRAY_COLOR);

		final Color color;

		Progress(Color color)
		{
			this.color = color;
		}
	}

	/** One NPC type in one map chunk. */
	@Value
	static class Row
	{
		AreaKey area;
		/** Heading for the chunk, e.g. "Lumbridge (3200, 3200)". */
		String heading;
		int kills;
		/** Spawns in the chunk, or null if unknown. */
		Integer total;
		int hiddenHere;

		Progress getProgress()
		{
			if (kills == 0)
			{
				return Progress.UNTOUCHED;
			}
			return total != null && kills >= total ? Progress.CLEARED : Progress.STARTED;
		}
	}

	private final Consumer<AreaKey> onForget;
	private final Consumer<Integer> onShowOnMap;
	private final JLabel summary = new JLabel();
	private final JPanel list = new JPanel();

	PermadeathPanel(Consumer<AreaKey> onForget, Runnable onOpenSettings, Consumer<Integer> onShowOnMap)
	{
		super(false);
		this.onForget = onForget;
		this.onShowOnMap = onShowOnMap;
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));
		JLabel title = new JLabel("NPC Permadeath");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		header.add(title, BorderLayout.WEST);
		JButton settings = new JButton("Settings");
		settings.setFont(FontManager.getRunescapeSmallFont());
		settings.setMargin(new Insets(1, 6, 1, 6));
		settings.setFocusPainted(false);
		settings.setToolTipText("Open the plugin settings");
		settings.addActionListener(e -> onOpenSettings.run());
		header.add(settings, BorderLayout.EAST);
		summary.setFont(FontManager.getRunescapeSmallFont());
		summary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.add(summary, BorderLayout.SOUTH);
		add(header, BorderLayout.NORTH);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(list, BorderLayout.CENTER);

		update(Collections.emptyList());
	}

	/** Rebuilds the list. Must be called on the Swing thread. */
	void update(List<Row> rows)
	{
		list.removeAll();
		int totalKills = rows.stream().mapToInt(Row::getKills).sum();
		long chunks = rows.stream().filter(r -> r.getKills() > 0).map(r -> r.getArea().getRegion()).distinct().count();
		if (rows.isEmpty())
		{
			summary.setText("Nothing slain yet.");
			JLabel hint = new JLabel("<html>Kill something. Every kill keeps one more of its kind hidden in that chunk of the map.</html>");
			hint.setFont(FontManager.getRunescapeSmallFont());
			hint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			list.add(hint);
		}
		else
		{
			summary.setText("<html>" + totalKills + " slain across " + chunks + " chunk" + (chunks == 1 ? "" : "s")
				+ ". Open the world map to see them.</html>");
			Map<String, List<Row>> byChunk = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
			for (Row row : rows)
			{
				byChunk.computeIfAbsent(row.getHeading(), h -> new ArrayList<>()).add(row);
			}
			byChunk.forEach((heading, chunkRows) ->
			{
				list.add(chunkHeader(heading, chunkRows.get(0).getArea().getRegion()));
				for (Row row : chunkRows)
				{
					list.add(rowPanel(row));
				}
				list.add(Box.createVerticalStrut(6));
			});
		}
		list.revalidate();
		list.repaint();
	}

	private JLabel chunkHeader(String heading, int region)
	{
		JLabel label = new JLabel(heading);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setBorder(BorderFactory.createEmptyBorder(4, 0, 2, 0));
		label.setAlignmentX(LEFT_ALIGNMENT);
		label.setToolTipText("Click to centre the world map on this chunk");
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onShowOnMap.accept(region);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				label.setForeground(ColorScheme.BRAND_ORANGE);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			}
		});
		return label;
	}

	private JPanel rowPanel(Row row)
	{
		JPanel panel = new JPanel(new GridBagLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 3));
		panel.setAlignmentX(LEFT_ALIGNMENT);
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));

		GridBagConstraints c = new GridBagConstraints();
		c.gridy = 0;
		c.insets = new Insets(0, 0, 0, 4);
		c.anchor = GridBagConstraints.WEST;

		JLabel name = new JLabel(row.getArea().getName());
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(row.getProgress() == Progress.UNTOUCHED ? ColorScheme.LIGHT_GRAY_COLOR : Color.WHITE);
		c.gridx = 0;
		c.weightx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		panel.add(name, c);

		String tally = row.getTotal() == null
			? row.getKills() + " slain"
			: row.getKills() + " / " + row.getTotal();
		JLabel count = new JLabel(tally, SwingConstants.RIGHT);
		count.setFont(FontManager.getRunescapeSmallFont());
		count.setForeground(row.getProgress().color);
		count.setToolTipText(row.getHiddenHere() + " hidden on this world"
			+ (row.getTotal() == null ? ", no spawn data yet" : ", " + row.getTotal() + " spawns known in this chunk"));
		c.gridx = 1;
		c.weightx = 0;
		c.fill = GridBagConstraints.NONE;
		panel.add(count, c);

		if (row.getKills() > 0)
		{
			JButton forget = new JButton("x");
			forget.setFont(FontManager.getRunescapeSmallFont());
			forget.setToolTipText("Forget these kills and bring them back");
			forget.setMargin(new Insets(0, 4, 0, 4));
			forget.setFocusPainted(false);
			forget.addActionListener(e -> onForget.accept(row.getArea()));
			c.gridx = 2;
			c.insets = new Insets(0, 0, 0, 0);
			panel.add(forget, c);
		}

		JPanel wrapper = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 1));
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.setAlignmentX(LEFT_ALIGNMENT);
		wrapper.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		panel.setPreferredSize(new Dimension(PANEL_WIDTH - 20, 26));
		wrapper.add(panel);
		return wrapper;
	}
}

package com.npcpermadeath;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Keeps the bundled data files fresh between plugin releases. A scheduled
 * job in the plugin repository regenerates them weekly; this fetches the
 * latest copy from GitHub once a week and caches it under the RuneLite
 * directory. Only data is fetched, never code.
 */
@Slf4j
class DataUpdater
{
	static final long REFRESH_MS = 7L * 24 * 60 * 60 * 1000;
	static final String KEY_PREFIX = "fetched.";
	private static final HttpUrl BASE = HttpUrl.parse(
		"https://raw.githubusercontent.com/Dewdul/npc-permadeath/master/src/main/resources/com/npcpermadeath/");
	private static final File DIR = new File(RuneLite.RUNELITE_DIR, "npc-permadeath");

	private final OkHttpClient httpClient;
	private final ConfigManager configManager;
	private final ClientThread clientThread;
	private final Set<String> inFlight = new HashSet<>();

	DataUpdater(OkHttpClient httpClient, ConfigManager configManager, ClientThread clientThread)
	{
		this.httpClient = httpClient;
		this.configManager = configManager;
		this.clientThread = clientThread;
	}

	/** The cached copy of a data file, or null if none has been fetched yet. */
	byte[] cached(String fileName)
	{
		File file = new File(DIR, fileName);
		if (!file.isFile())
		{
			return null;
		}
		try
		{
			return Files.readAllBytes(file.toPath());
		}
		catch (IOException e)
		{
			log.warn("Could not read cached {}", fileName, e);
			return null;
		}
	}

	/**
	 * Fetches the file if the cached copy is a week old or missing. The
	 * callback runs on the client thread, only when the content changed.
	 */
	void refreshIfStale(String fileName, long now, Consumer<byte[]> onChanged)
	{
		String key = KEY_PREFIX + fileName;
		Long fetched = configManager.getConfiguration(NpcPermadeathConfig.GROUP, key, Long.class);
		if (fetched != null && now - fetched < REFRESH_MS && new File(DIR, fileName).isFile())
		{
			return;
		}
		if (!inFlight.add(fileName))
		{
			return;
		}
		HttpUrl url = BASE.newBuilder().addPathSegment(fileName).build();
		httpClient.newCall(new Request.Builder().url(url).build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Could not refresh {}", fileName, e);
				clientThread.invoke(() -> inFlight.remove(fileName));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				byte[] body = null;
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						body = r.body().bytes();
					}
				}
				catch (IOException e)
				{
					log.debug("Could not read refreshed {}", fileName, e);
				}
				byte[] fresh = body;
				clientThread.invoke(() ->
				{
					inFlight.remove(fileName);
					if (fresh == null || fresh.length == 0)
					{
						return;
					}
					configManager.setConfiguration(NpcPermadeathConfig.GROUP, key, now);
					byte[] previous = cached(fileName);
					if (previous != null && Arrays.equals(previous, fresh))
					{
						return;
					}
					if (store(fileName, fresh))
					{
						log.debug("Refreshed {} ({} bytes)", fileName, fresh.length);
						onChanged.accept(fresh);
					}
				});
			}
		});
	}

	private static boolean store(String fileName, byte[] content)
	{
		try
		{
			if (!DIR.isDirectory() && !DIR.mkdirs())
			{
				return false;
			}
			File tmp = new File(DIR, fileName + ".tmp");
			Files.write(tmp.toPath(), content);
			Files.move(tmp.toPath(), new File(DIR, fileName).toPath(), StandardCopyOption.REPLACE_EXISTING);
			return true;
		}
		catch (IOException e)
		{
			log.warn("Could not store {}", fileName, e);
			return false;
		}
	}
}
